@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class DartClient {
 static final BlockPos Q=new BlockPos(960,205,8);static int ticks,stage,shots,hits,melee;static long due;static boolean deny=true,record=true;static final List<Long> times=new ArrayList<>();static final List<Cow> adults=new ArrayList<>();static WorkerGolem g;static SealEntity s;static net.minecraft.world.entity.monster.zombie.Zombie victim;static net.minecraft.world.entity.animal.wolf.Wolf pet;static Cow baby;static GolemDart last;static GolemBuilder builder;
 static boolean mode(){return System.getProperty("thaumcraft.thaumaturgyProbe","").equals("dart-client");}
 @SubscribeEvent public static void joined(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(mode()&&e.getEntity() instanceof GolemDart d&&d.level() instanceof ServerLevel l){last=d;shots++;if(record)times.add(l.getGameTime());check(d.pickup==AbstractArrow.Pickup.DISALLOWED,"Dart can be picked up");}}
 @SubscribeEvent public static boolean attack(net.minecraftforge.event.entity.living.LivingAttackEvent e){if(!mode())return false;if(e.getSource().getDirectEntity() instanceof GolemDart){hits++;return deny;}if(g!=null&&e.getSource().getDirectEntity()==g)melee++;return false;}
 static WorkerGolem spawn(ServerPlayer p){var w=LogisticsClient.spawn(p,new GolemDesign(3,1,4,0),Q);w.setCustomName(Component.literal("Native dart worker"));return w;}
 static void killDarts(ServerLevel l){for(var d:l.getEntitiesOfClass(GolemDart.class,new AABB(Q).inflate(40)))d.discard();}
 static void wall(ServerLevel l,boolean on){for(var q:BlockPos.betweenClosed(Q.offset(6,0,-3),Q.offset(6,4,3)))l.setBlockAndUpdate(q,(on?Blocks.STONE:Blocks.AIR).defaultBlockState());}
 static GolemDart launch(ServerPlayer p,LivingEntity target){check(GolemDart.fire(p.level(),g,p,s,target),"Direct policy dart launch failed target="+target.getName().getString()+" protected="+thaumcraft.thaumaturgy.SpellEngine.protectedTarget(p,target)+" eligible="+GolemCombat.eligible(p.level(),p,g,s,target)+" alive="+target.isAlive()+" mode="+g.mode()+" state="+s.active()+" range="+g.distanceTo(target));return last;}
 static GolemDart snapshot(ServerPlayer p,GolemDart d){var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());d.saveWithoutId(out);var tag=out.buildResult();tag.putByte("pickup",(byte)1);var copy=new GolemDart(GolemContent.DART.get(),p.level());copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),tag));check(copy.targetId().equals(victim.getUUID())&&copy.sealPos().equals(s.getBlockPos())&&copy.expires()==d.expires()&&copy.pickup==AbstractArrow.Pickup.DISALLOWED&&copy.mayHit(victim),"Live dart snapshot lost binding or pickup restriction");d.discard();copy.setUUID(UUID.randomUUID());p.level().addFreshEntity(copy);return copy;}
 static void policy(ServerPlayer p){var l=p.level();g.setMode(0);var d=snapshot(p,launch(p,victim));check(!d.mayHit(p)&&!d.mayHit(pet)&&!d.mayHit(g),"Dart can hit owner, pet or worker");check(s.edit(p,1)&&!d.mayHit(victim),"Edited seal did not invalidate flying dart");d.discard();d=launch(p,victim);s.channel=1;check(!d.mayHit(victim),"Changed channel did not invalidate dart");s.channel=0;g.setMode(2);check(!d.mayHit(victim),"Paused worker dart remains harmful");d.discard();g.setMode(0);d=launch(p,victim);l.setBlockAndUpdate(s.getBlockPos().north(),Blocks.REDSTONE_BLOCK.defaultBlockState());check(!d.mayHit(victim),"Powered seal dart remains harmful");l.removeBlock(s.getBlockPos().north(),false);d.discard();
 var other=new ServerPlayer(p.level().getServer(),l,new GameProfile(UUID.randomUUID(),"DartPVP"),ClientInformation.createDefault());other.setPos(Vec3.atBottomCenterOf(Q.east(12)));other.getAbilities().instabuild=false;s.guardMode=2;boolean pvp=l.getGameRules().get(net.minecraft.world.level.gamerules.GameRules.PVP);l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.PVP,false,l.getServer());check(!GolemDart.fire(l,g,p,s,other),"PVP-disabled dart launched");l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.PVP,true,l.getServer());d=launch(p,other);check(d.mayHit(other),"Valid survival PVP target rejected");l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.PVP,false,l.getServer());check(!d.mayHit(other),"In-flight dart bypassed changed PVP rule");l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.PVP,true,l.getServer());other.getAbilities().instabuild=true;check(!d.mayHit(other),"In-flight dart bypassed creative protection");d.discard();l.getGameRules().set(net.minecraft.world.level.gamerules.GameRules.PVP,pvp,l.getServer());s.guardMode=0;g.setMode(2);Thaumcraft.LOGGER.info("DART_POLICY_OK: live NBT, no pickup, target binding, owner/pet, edited/powered seal, changed channel, Stay, PvP and creative protection");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!mode()||e.server().isDedicatedServer()||e.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=e.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
 if(stage==0){knowledge(p);p.setGameMode(GameType.SURVIVAL);p.getInventory().clearContent();for(int x=59;x<=62;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);for(var ent:l.getEntitiesOfClass(LivingEntity.class,new AABB(Q).inflate(40)))if(!(ent instanceof net.minecraft.world.entity.player.Player))ent.discard();for(var q:BlockPos.betweenClosed(Q.offset(-8,0,-6),Q.offset(26,7,6)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(-8,-1,-6),Q.offset(26,-1,6)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());s=GolemProbe.seal(p,SealKind.GUARD_ADVANCED,Q.east(10));s.radius=8;l.setBlockAndUpdate(s.getBlockPos().north(),Blocks.REDSTONE_BLOCK.defaultBlockState());p.teleportTo(l,Q.getX()+10.5,Q.getY(),Q.getZ()+4.5,Set.of(),0,0,true);stage=1;due=now+60;return;}
 if(stage==1&&now>=due){victim=BatRiftClient.mob(p,Vec3.atBottomCenterOf(Q.east(12)));pet=new net.minecraft.world.entity.animal.wolf.Wolf(EntityTypes.WOLF,l);pet.setPos(Vec3.atBottomCenterOf(Q.east(6).south(2)));pet.setNoAi(true);pet.tame(p);l.addFreshEntity(pet);g=spawn(p);g.setChannel(1);stage=2;due=now+50;return;}
 if(stage==2&&now>=due){check(shots==0&&victim.getHealth()==20,"Wrong-channel dart fired");g.setChannel(0);stage=3;due=now+50;return;}
 if(stage==3&&now>=due){check(shots==0&&victim.getHealth()==20,"Powered seal fired darts");l.removeBlock(s.getBlockPos().north(),false);stage=4;due=now+400;return;}
 if(stage==4){check(now<due,"Physical dart cancellation timeout shots="+shots+" hits="+hits+" pos="+g.position());if(hits<2)return;check(victim.getHealth()==20&&melee==0&&g.distanceTo(victim)>8&&p.getHealth()==20&&pet.getHealth()==pet.getMaxHealth(),"Canceled dart hurt target or used melee");for(int n=1;n<times.size();n++)check(times.get(n)-times.get(n-1)>=20&&times.get(n)-times.get(n-1)<=25,"Dart cadence outside 20–25: "+times);record=false;g.setMode(2);stage=5;due=now+15;Thaumcraft.LOGGER.info("DART_CANCEL_OK: two actual physical impacts canceled by Forge, ranged stand-off, cadence and no owner/pet damage");return;}
 if(stage==5&&now>=due){killDarts(l);policy(p);deny=false;g.setMode(0);var d=launch(p,victim);wall(l,true);stage=6;due=now+45;return;}
 if(stage==6&&now>=due){check(victim.getHealth()==20&&last.isRemoved(),"Dart passed through solid wall");wall(l,false);killDarts(l);g.setMode(2);g.setMode(0);var d=launch(p,victim);snapshot(p,d);stage=7;due=now+400;return;}
 if(stage==7){check(now<due,"Restored physical dart did not damage target");if(victim.getHealth()>=20)return;check(melee==0&&g.distanceTo(victim)>8&&g.cargo.isEmpty(),"Darter used melee/cargo ammo");g.setMode(2);killDarts(l);victim.discard();GolemClient.remove(s);pet.discard();s=GolemProbe.seal(p,SealKind.BUTCHER,Q.east(10));s.radius=8;for(int n=0;n<4;n++)adults.add(TaskProbe.cow(p,Q.east(11+n).south(n%2==0?0:2),false));baby=TaskProbe.cow(p,Q.east(12).north(2),true);g.setMode(0);stage=8;due=now+1200;Thaumcraft.LOGGER.info("DART_DAMAGE_OK: solid wall stopped a dart; saved/restored physical projectile caused real ranged damage without ammunition cargo");return;}
 if(stage==8){long alive=adults.stream().filter(LivingEntity::isAlive).count();check(alive>=2&&baby.isAlive(),"Dart butcher killed protected population");check(now<due,"Dart butcher timeout adults="+alive+" shots="+shots);if(alive!=2)return;stage=9;due=now+100;return;}
 if(stage==9&&now>=due){check(adults.stream().filter(LivingEntity::isAlive).count()==2&&baby.getHealth()==baby.getMaxHealth(),"In-flight darts harmed breeding pair/baby");g.setMode(2);killDarts(l);GolemClient.remove(s);for(var a:adults)if(a.isAlive())a.discard();baby.discard();g.cargo.setItem(0,new ItemStack(Items.GOLD_INGOT,11));g.setHealth(4);var design=g.design();p.setItemInHand(InteractionHand.MAIN_HAND,item("golem_bell"));p.setShiftKeyDown(true);check(g.interact(p,InteractionHand.MAIN_HAND,Vec3.ZERO)==InteractionResult.SUCCESS&&g.isRemoved(),"Darter packing failed");p.setShiftKeyDown(false);var pack=java.util.stream.IntStream.range(0,36).mapToObj(i->p.getInventory().getItem(i)).filter(v->v.getItem() instanceof GolemPlacer&&v.get(GolemContent.DESIGN.get()).arms()==4).findFirst().orElseThrow();check(pack.get(GolemContent.DESIGN.get()).equals(design)&&Math.abs(pack.get(GolemContent.HEALTH.get())-.25F)<.001,"Packed darter lost design or healed");check(l.getEntitiesOfClass(ItemEntity.class,new AABB(g.blockPosition()).inflate(3),v->v.getItem().is(Items.GOLD_INGOT)&&v.getItem().getCount()==11).size()==1,"Darter packing duplicated cargo");check(l.getEntitiesOfClass(ItemEntity.class,new AABB(Q).inflate(40),v->v.getItem().is(Items.ARROW)).isEmpty(),"Darts generated recoverable arrows");l.setBlockAndUpdate(Q.east(10).south(2),GolemContent.BUILDER.get().defaultBlockState());builder=(GolemBuilder)l.getBlockEntity(Q.east(10).south(2));GolemProbe.giveComponents(p,new GolemDesign(0,0,4,0));p.teleportTo(l,Q.getX()+10.5,Q.getY(),Q.getZ()+4.5,Set.of(),0,0,true);p.openMenu(builder);stage=10;Thaumcraft.LOGGER.info("DART_BUTCHER_PACK_OK: population of two and baby protected from in-flight darts; packed arms/health/cargo and no arrow drops");return;}
 if(stage==10&&builder.working()){check(builder.draft.arms()==4&&!builder.edit(p,2),"Paid native dart GUI not locked");stage=11;Thaumcraft.LOGGER.info("DART_CLIENT_OK: physical ranged combat, cancellations, protected targets, flight NBT, butcher and native paid GUI");}
 }
}
